const dtiProfiles = inputs.applicants.map((a) => {
  const dti = (a.monthlyDebt / a.monthlyIncome) * 100;
  let dtiScore = 100 - (dti * 1.5);
  if (dtiScore < 0) dtiScore = 0;
  return {
    ...a,
    dtiRatio: Math.round(dti * 100) / 100,
    dtiScore: Math.round(dtiScore * 100) / 100,
  };
});
return { dtiProfiles };
```

